// Two-Color Cyclic Noise (Ray Marching)
// TWO-COLOR variant of "Noise": same 3D cyclic noise core, but the
// noise drives a SINGLE mix scalar between u_col2 and u_col1. This way the
// dock Texture Color pickers (col1/col2) really control the result, unlike
// the palette version that generates a continuous spectrum.
//
// Engine variables available in this block (Ray Marching tab):
//   pModel       = hit point on the surface (vec3, model space)
//   n_model      = surface normal at the hit point (vec3)
//   textureCol   = color to assign (already initialized to ubuf.color)
//   ubuf.u_time  = animated time; ubuf.u_col1 / ubuf.u_col2 = dock colors
// NB: no mainImage, no return, no gl_FragCoord in this tab.

// --- Cyclic noise 3D: iterated loop of |dot(cos,sin)| with distortion and rotation ---
float result = 0.0;
float z = 0.95;
float distort = 2.1;
float dstAmount = 0.10;
float wsum = 0.0;

mat3 m2 = mat3(
    0.97367,  0.22798, 0.0,
   -0.22798,  0.97367, 0.0,
    0.0,      0.0,     1.0) * 1.5;

vec3 p = pModel * 2.3 + vec3(0.0, 0.0, ubuf.u_time * 0.05);

for (int i = 0; i < 8; i++) {
    p += sin(p.yzx * distort + ubuf.u_time * 0.27 * pow(distort, 1.35)) * dstAmount;
    result += abs(dot(cos(p), sin(p.zxy)) * z);
    wsum   += z;
    z       *= 0.65;
    distort *= 1.35;
    p        = m2 * p;
}
float ncyc = clamp(result / wsum, 0.0, 1.0);   // ~[0,1]

// soft contrast curve to separate the two colors well
float tcol = smoothstep(0.25, 0.75, ncyc);

// ONLY the two dock colors: interpolation of a single scalar
vec3 bicolor = mix(ubuf.u_col2, ubuf.u_col1, tcol);

// NEUTRAL edge sheen (gray): brightens the ridges without introducing
// hues foreign to the two chosen colors
float fres = pow(1.0 - abs(n_model.z), 2.0);
bicolor += vec3(fres * 0.12 * ncyc);

textureCol = bicolor;
